<script setup>
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { echoNotes } from '../../data/adventures.js';
import { echoSequence,judgeEcho } from '../../room/adventureGames.js';
import { useLocalDraft } from '../../composables/useLocalDraft.js';
import { useInteractionAudio } from '../../composables/useInteractionAudio.js';
import { recordActivity } from '../../room/activityLog.js';
const bases={easy:3,normal:5,hard:7};
const validate=v=>{if(!v||v.version!==1)throw new Error('invalid echo');return {version:1,seed:Number.isSafeInteger(v.seed)?v.seed:1,level:Object.hasOwn(bases,v.level)?v.level:'easy',round:Math.max(0,Math.min(4,Math.floor(v.round)||0)),answers:(Array.isArray(v.answers)?v.answers:[]).filter(n=>Number.isInteger(n)&&n>=0&&n<6).slice(0,9),best:Object.fromEntries(Object.keys(bases).map(k=>[k,Math.max(0,Math.min(100,Number(v.best?.[k])||0))]))};};
const {state,saved}=useLocalDraft('hitori-room:echo:v1',{version:1,seed:Date.now(),level:'easy',round:0,answers:[],best:{easy:0,normal:0,hard:0}},validate);
const audio=useInteractionAudio('melody-echo'),sequence=computed(()=>echoSequence(state.value.seed+state.value.round*101,bases[state.value.level]+state.value.round)),score=computed(()=>judgeEcho(sequence.value,state.value.answers));
const phase=ref(state.value.answers.length===sequence.value.length?'result':'ready'),active=ref(-1),message=ref('先听一小段，再把旋律弹回来。'),instrument=ref('guitar');
let generation=0,timers=[],alive=true;
function cancel(){generation++;timers.forEach(clearTimeout);timers=[];active.value=-1;audio.stop();phase.value=state.value.answers.length===sequence.value.length?'result':'ready';}
async function listen(compare=false,slow=false){cancel();const token=++generation;if(!compare)state.value.answers=[];phase.value=compare?'compare':'listening';message.value=compare?'慢慢对照一下每个落点。':'先听，等旋律结束后再输入。';const enabled=await audio.setEnabled(true);if(!alive||token!==generation)return;if(!enabled||document.hidden){cancel();message.value='声音暂未准备好，请再点一次播放。';return;}const beat=slow?900:520;sequence.value.forEach((note,index)=>{timers.push(setTimeout(()=>{if(token!==generation||document.hidden)return;active.value=note;audio.play(instrument.value,echoNotes[note].frequency);},index*beat));});timers.push(setTimeout(()=>{if(token!==generation)return;active.value=-1;phase.value=compare?'result':'input';message.value=compare?'可以看看哪些音不一样，再挑战下一轮。':'轮到你了：轻点琴键，或按数字 1–6。';},sequence.value.length*beat+200));}
function input(note){if(phase.value!=='input')return;state.value.answers.push(note);audio.play(instrument.value,echoNotes[note].frequency);active.value=note;if(state.value.answers.length===sequence.value.length){phase.value='result';active.value=-1;state.value.best[state.value.level]=Math.max(state.value.best[state.value.level],score.value.accuracy);message.value=score.value.perfect?'每一个音都接住了。这个小回声，是你弹出来的。':'认真听过，就多记住了一点。可以慢放对照，再试下一轮。';recordActivity('echo',`${sequence.value.length} 个音 · ${score.value.correct} 个接对`,`${state.value.seed}:${state.value.round}:${state.value.answers}`);}}
function next(){cancel();if(state.value.round===4){state.value.seed=Date.now();state.value.round=0;}else state.value.round++;state.value.answers=[];phase.value='ready';message.value='下一轮准备好了，先点播放听一遍。';}
function levelChanged(){cancel();state.value.round=0;state.value.seed=Date.now();state.value.answers=[];phase.value='ready';}
function keyboard(event){if(document.hidden||event.repeat||event.ctrlKey||event.metaKey||/INPUT|SELECT|TEXTAREA/.test(event.target.tagName)||event.target.isContentEditable||event.target.closest?.('.room-companion'))return;const note=Number(event.key)-1;if(note>=0&&note<6){event.preventDefault();input(note);}}
function hidden(){if(document.hidden){cancel();message.value='离开页面时已暂停；回来后可以重新听本轮。';}}
watch(audio.enabled,value=>{if(!value&&(phase.value==='listening'||phase.value==='compare')){cancel();message.value='已静音，准备好后可以重新听。';}});
onBeforeRouteLeave(cancel);
onMounted(()=>{window.addEventListener('keydown',keyboard);document.addEventListener('visibilitychange',hidden);});onBeforeUnmount(()=>{alive=false;cancel();window.removeEventListener('keydown',keyboard);document.removeEventListener('visibilitychange',hidden);});
</script>
<template><section class="room-panel" aria-labelledby="echo-title"><div class="play-heading"><div><p class="play-eyebrow">LISTEN & REMEMBER / 留住刚刚听见的声音</p><h2 id="echo-title">把这一小段，弹回来。</h2><p class="room-intro">听觉记忆挑战，共五轮，旋律会慢慢变长。结果页可以慢放、逐音对照，没有时间限制。</p></div><span class="play-number" aria-hidden="true">10</span></div>
  <div class="room-fields"><label class="room-field">练习长度<select id="echo-level" v-model="state.level" :disabled="['listening','compare','input'].includes(phase)" @change="levelChanged"><option value="easy">轻松 · 从 3 个音开始</option><option value="normal">标准 · 从 5 个音开始</option><option value="hard">挑战 · 从 7 个音开始</option></select></label><label class="room-field">示范音色<select v-model="instrument" :disabled="phase==='listening'||phase==='compare'"><option value="guitar">轻轻拨弦</option><option value="bass">柔和低音</option></select></label></div>
  <div class="echo-stage" :data-phase="phase"><p class="adventure-kicker">ROUND 0{{state.round+1}} / 05</p><strong>{{phase==='listening'?'先听这一段':phase==='input'?'轮到你来弹':phase==='compare'?'放慢一点，再听一遍':phase==='result'?'这一次，你接住了多少？':'准备好了，就让第一声响起'}}</strong><div class="echo-slots" :aria-label="`已输入${state.answers.length}个，共${sequence.length}个音`"><span v-for="(_,index) in sequence" :key="index" :class="{'is-filled':state.answers[index]!=null}">{{state.answers[index]!=null?echoNotes[state.answers[index]].label:'·'}}</span></div><p>本级最高准确率 {{state.best[state.level]}}%</p></div>
  <div class="echo-keys" role="group" aria-label="六个旋律琴键"><button v-for="(note,index) in echoNotes" :key="note.key" type="button" :aria-label="`弹奏${note.label}，数字${note.key}`" :disabled="phase!=='input'" :class="{'is-active':active===index}" :style="{'--echo-color':note.color}" @click="input(index)"><span>{{note.key}}</span><strong>{{note.label}}</strong></button></div>
  <div class="room-actions"><button v-if="phase==='ready'||phase==='input'" id="echo-listen" type="button" class="primary" @click="listen()">{{phase==='input'?'重新听本轮':'播放本轮旋律'}}</button><button v-if="phase==='listening'||phase==='compare'" type="button" @click="cancel();message='已停止，随时可以重听。'">停止示范</button><template v-if="phase==='result'"><button id="echo-compare" type="button" @click="listen(true,true)">慢放对照</button><button type="button" @click="listen()">重新挑战本轮</button><button id="echo-next" type="button" class="primary" @click="next">{{state.round===4?'五轮完成，开启新的练习 →':'继续下一轮 →'}}</button></template></div>
  <div v-if="phase==='result'||phase==='compare'" class="echo-result"><span class="adventure-score">{{score.accuracy}}%</span><p>接对 {{score.correct}} / {{score.total}} 个音</p><div class="echo-comparison"><span>听见的旋律</span><div><span v-for="(note,index) in sequence" :key="index" :style="{background:echoNotes[note].color}">{{echoNotes[note].label}}</span></div><span>你的回声</span><div><span v-for="(note,index) in state.answers" :key="index" :class="{'is-wrong':note!==sequence[index]}" :style="{background:echoNotes[note].color}">{{echoNotes[note].label}} {{note===sequence[index]?'✓':'·'}}</span></div></div></div>
  <p class="room-status" role="status">{{message}}</p><p class="play-footer-note">{{saved?'本轮与最高准确率会保存在本机。':'当前浏览器无法保存，本次仍可挑战。'}} 示范中不能输入；重听会清空本轮输入。切后台、静音或离页会停止示范，回来后不会自动播放。</p>
</section></template>
<style scoped>.echo-stage{text-align:center;padding:30px 20px;background:#e7dde6;border:1px solid #bca5bc}.echo-stage>strong{font-size:clamp(19px,3vw,28px);display:block;color:#614b65;margin:15px 0}.echo-stage>p:last-child{font-size:11px;color:#93758a}.echo-slots{display:flex;justify-content:center;flex-wrap:wrap;gap:8px;margin:25px 0}.echo-slots>span{min-width:42px;min-height:44px;display:grid;place-items:center;background:#fff6eb;border-bottom:3px solid #c8adb9;font:15px monospace}.echo-slots>.is-filled{border-color:#9b6889;background:#f0dce7}.echo-keys{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin:22px 0}.echo-keys button{min-height:110px;display:flex;flex-direction:column;justify-content:space-between;background:#fff7e8;border-top:6px solid var(--echo-color);opacity:1;padding:15px 5px}.echo-keys button>span{font:10px monospace;color:#9c7b8d}.echo-keys button>strong{font-size:18px}.echo-keys .is-active{background:var(--echo-color);box-shadow:0 3px 12px #a0809b66}.echo-result{padding:25px;border:1px solid #d9c2ce;background:#f3e8e1;text-align:center}.echo-result>p{font-size:12px}.echo-comparison{display:grid;gap:12px;text-align:left;font-size:11px}.echo-comparison>div{display:flex;flex-wrap:wrap;gap:6px}.echo-comparison>div>span{padding:10px 12px;color:#4b4152;font:13px monospace;min-width:42px;text-align:center}.echo-comparison .is-wrong{outline:2px dashed #9c5d7b;outline-offset:-3px}@media(max-width:500px){.echo-keys{gap:5px}.echo-keys button{min-height:90px}.echo-keys button>strong{font-size:14px}.echo-stage{padding:20px 12px}.echo-slots>span{min-width:32px;font-size:12px}.echo-slots{gap:5px}.echo-result{padding:18px}}</style>
